  ('AEEE', 'cutoffs', 'estimate', 'Admission is by rank, not a fixed cutoff. B.Tech CSE at the Coimbatore and Bengaluru campuses usually closes within roughly the top 2,000–5,000 ranks; core branches and other campuses close much higher (up to ~20,000–40,000).', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('AMU Entrance', 'cutoffs', 'estimate', 'AMU publishes merit lists, not fixed cutoffs. Half of the seats in most courses are reserved for AMU''s internal students, so external candidates need a high merit position (often the top ~5–10% of applicants for popular courses).', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('CUCET', 'cutoffs', 'estimate', 'No admission cutoff: the score mainly decides the scholarship (top scorers get large tuition waivers). Admission also needs the course''s Class 12 eligibility.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('CUSAT CAT', 'cutoffs', 'estimate', 'Admission is by CAT rank. B.Tech CSE/IT at the School of Engineering usually closes within roughly the top 1,000–3,000 ranks; other branches go higher.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('FRI Entrance Examination', 'cutoffs', 'estimate', 'No published cutoff; admission by rank in the entrance test for the limited M.Sc seats (often ~30–40 per course).', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('FTII SRFTI JET', 'cutoffs', 'estimate', 'No published cutoff. JET scores shortlist candidates (usually several times the seats) for orientation and interview; final selection is on the combined score.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('GBPUAT Entrance Exam', 'cutoffs', 'estimate', 'Admission is by rank; no fixed cutoff. Seats are few, so popular programmes usually close within the top few hundred ranks.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('GUJCET', 'cutoffs', 'estimate', 'No qualifying cutoff. For engineering, merit = 50% Class 12 theory marks (PCM) + 50% GUJCET. Top government colleges (e.g. LD College of Engineering) usually close around the top 1–5 percentile of the merit list for CSE/IT.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('IAT', 'cutoffs', 'estimate', 'No published qualifying cutoff; seats are allotted by IAT rank across the IISERs. General-category BS-MS seats usually close within roughly the top 1,500–3,000 ranks.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('ICAR AIEEA', 'cutoffs', 'estimate', 'Rank-based; there is no published qualifying cutoff. Popular subjects at top agricultural universities usually close within the top few hundred ranks in that subject.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('IISc BS', 'cutoffs', 'estimate', 'Very competitive (about 100–130 seats). Offers usually go to candidates with a strong JEE Advanced or JEE Main rank (typically within the top few thousand) or a top NEET-UG rank.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('IKSV Aptitude Test', 'cutoffs', 'estimate', 'No published cutoff; selection is by aptitude/practical test and interview in the chosen art form.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('ISI Admission Test', 'cutoffs', 'estimate', 'No published cutoff; candidates are shortlisted for the interview on their test score (only a small fraction of applicants).', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('JET', 'cutoffs', 'estimate', 'No published cutoff; admission is on the test score and interview, with Class 12 eligibility.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('KCET', 'cutoffs', 'estimate', 'No qualifying cutoff; the rank uses 50% Class 12 PCM marks + 50% CET marks. Government-quota CSE at the top Bengaluru colleges (e.g. RVCE, BMSCE) usually closes within roughly ranks 300–2,500 (general merit).', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('KEAM', 'cutoffs', 'estimate', 'To get an engineering rank you need at least 10 marks in each paper (5 for SC/ST); the rank combines Class 12 marks and KEAM. Top government colleges (e.g. CET Thiruvananthapuram) usually close CSE within roughly the top 1,000–2,000 ranks.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('KIITEE', 'cutoffs', 'estimate', 'No fixed cutoff; admission is by rank. B.Tech CSE usually closes within roughly the top 10,000–20,000 ranks.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('LPUNEST', 'cutoffs', 'estimate', 'No admission cutoff for most programmes: the score mainly decides the scholarship. Some programmes need a minimum score (around 30–40%).', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('Lucknow University UGET', 'cutoffs', 'estimate', 'Merit lists are by UGET score; popular programmes (e.g. B.Com Hons, BBA) usually need a score in the top ~10–20% of candidates.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('MAH MBA CET', 'cutoffs', 'estimate', 'No qualifying cutoff for counselling. JBIMS and SIMSREE usually need about the 99th percentile or higher; other good Mumbai/Pune colleges roughly 90–98.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('MANIPAL MET', 'cutoffs', 'estimate', 'Admission is by rank; no fixed cutoff. B.Tech CSE at MIT Manipal usually closes within roughly the top 3,000–8,000 ranks.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('MH CET Law', 'cutoffs', 'estimate', 'No qualifying cutoff for counselling. Government Law College Mumbai usually needs roughly the top 1–2% of scores (about 110+ out of 150 for the 5-year course).', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('MHT CET', 'cutoffs', 'estimate', 'No qualifying cutoff. COEP Pune and VJTI Mumbai CSE usually close at about the 99.5th percentile or higher; good private colleges roughly 95–99.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('MSE Entrance Test', 'cutoffs', 'estimate', 'No published cutoff; admission is by entrance test rank for the limited M.A. seats.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('NCHMCT JEE', 'cutoffs', 'estimate', 'Admission is by rank. Top government IHMs (Pusa Delhi, Mumbai, Bengaluru, Chennai) usually close within roughly the top 1,000–2,500 general ranks.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('NID DAT', 'cutoffs', 'estimate', 'NID does not publish a qualifying cutoff. DAT Prelims shortlists for the Mains (studio test and interview); the final merit combines both.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('NIFT Entrance', 'cutoffs', 'estimate', 'NIFT does not publish cutoffs. B.Des merit = written test + situation test; Delhi and Mumbai campuses usually close within the top few hundred ranks in the general category.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('NMAT', 'cutoffs', 'estimate', 'No common cutoff. NMIMS Mumbai usually needs a scaled score of about 220–240 or more; other participating schools accept lower scores.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('NPAT', 'cutoffs', 'estimate', 'No published cutoff; NMIMS ranks applicants by score for each programme and campus.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('OJEE', 'cutoffs', 'estimate', 'Admission is by rank; there is no qualifying cutoff. Most government seats are now filled on JEE Main, with OJEE ranks used for the remaining seats.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('PAU CET', 'cutoffs', 'estimate', 'Admission is by rank; no fixed cutoff. B.Sc (Hons) Agriculture usually closes within the top few hundred ranks for the general category.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('PGIMER', 'cutoffs', 'estimate', 'PGIMER publishes merit lists, not cutoffs. MD/MS seats in popular branches usually go to the top ~1% of candidates.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('PU CET (UG)', 'cutoffs', 'estimate', 'Admission is by rank; no fixed cutoff. B.Pharm and B.Sc (Hons) seats usually close within the top few hundred ranks.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('SLAT', 'cutoffs', 'estimate', 'No published cutoff. Symbiosis Law School Pune usually needs about the top 1–5% of SLAT scores; other campuses accept lower scores.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('SNUSAT', 'cutoffs', 'estimate', 'No published cutoff; admission is on SNUSAT score plus interview, with Class 12 eligibility.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('SRMJEEE', 'cutoffs', 'estimate', 'Admission is by rank. B.Tech CSE at Kattankulathur usually closes within roughly the top 5,000–10,000 ranks; other campuses and branches go higher.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('TANCET', 'cutoffs', 'estimate', 'No qualifying cutoff for counselling. Anna University''s own departments (e.g. DoMS) usually need roughly 70–80+ marks out of 100.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('TIFR GS', 'cutoffs', 'estimate', 'No published cutoff; the written test shortlists a small fraction of candidates for interviews.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('TNEA', 'cutoffs', 'estimate', 'Cutoff marks are out of 200 (Maths 100 + Physics 50 + Chemistry 50). CSE at CEG Anna University usually closes at about 199–200; good private colleges roughly 185–195.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('TS EAMCET', 'cutoffs', 'estimate', 'Admission is by rank. CSE at JNTU Hyderabad and Osmania usually closes within roughly the top 1,000–3,000 ranks.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('TS ICET', 'cutoffs', 'estimate', 'Admission is by rank; Osmania and JNTU MBA seats usually close within roughly the top 1,000–5,000 ranks.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('UCEED', 'cutoffs', 'estimate', 'Admission is by UCEED rank across the participating IITs. IIT Bombay B.Des usually closes within roughly the top 100–200 general ranks.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('UGEE (IIIT Hyderabad)', 'cutoffs', 'estimate', 'Admission is on UGEE score plus interview; only roughly the top 200–400 candidates are called for interview for about 100–150 seats.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('VITEEE', 'cutoffs', 'estimate', 'Admission is by rank. B.Tech CSE at VIT Vellore usually closes within roughly the top 10,000–20,000 ranks (lower fee categories close earlier).', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('WBJEE', 'cutoffs', 'estimate', 'Admission is by rank. Jadavpur University CSE usually closes within roughly the top 100–200 ranks; other branches and colleges go much higher.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('XIC OET', 'cutoffs', 'estimate', 'No published cutoff; selection is on the online entrance test plus interview.', 'Based on typical cutoffs and closing ranks in recent years. Actual cutoffs change every year with paper difficulty, seats and category.', null, null, null, null),
  ('NID DAT', 'dates', 'estimate', 'Applications ~September–November 2026 · DAT Prelims ~December 2026 · Mains ~March–May 2027.', 'Based on when this exam was held in recent cycles (2023–2026). The conducting body announces the exact dates.', null, null, null, null),
  ('FTII SRFTI JET', 'syllabus', 'estimate', 'Two parts: (1) general awareness, reasoning and aptitude (MCQs, common to all courses); (2) a course-specific section testing visual sense, storytelling and film/TV awareness (descriptive).', 'Based on the exam''s usual pattern in recent years.', null, null, null, null),
  ('IISc BS', 'syllabus', 'estimate', 'No separate test. Preparation follows the JEE (Physics, Chemistry, Mathematics) or NEET (Physics, Chemistry, Biology) syllabus at the Class 11–12 level.', 'Based on the exam''s usual pattern in recent years.', null, null, null, null),
  ('IKSV Aptitude Test', 'syllabus', 'estimate', 'A practical/aptitude test in the chosen art (vocal or instrumental music, dance, fine arts) plus basic theory and a short interview.', 'Based on the exam''s usual pattern in recent years.', null, null, null, null),
  ('INSPIRE Scholarship', 'syllabus', 'estimate', 'There is no exam or syllabus. INSPIRE-SHE is merit-based: the top 1% in your Class 12 board (or a JEE/NEET rank within the top 10,000, or certain olympiad/NTSE/JBNSTS awards), while studying a natural or basic science course.', 'Based on the exam''s usual pattern in recent years.', null, null, null, null),
  ('Lucknow University UGET', 'syllabus', 'estimate', 'An objective test of general knowledge, reasoning, English and the programme''s Class 12 subjects (e.g. Commerce for B.Com, Mathematics for BCA).', 'Based on the exam''s usual pattern in recent years.', null, null, null, null),
  ('NISM Certifications', 'syllabus', 'estimate', 'Each certification has its own NISM workbook (for example Series V-A Mutual Fund Distributors, Series VIII Equity Derivatives, Series XV Research Analyst). Tests are usually 100 MCQs/100 marks in 2 hours, with 50–60% needed to pass.', 'Based on the exam''s usual pattern in recent years.', null, null, null, null),
  ('NSD Entrance Exam', 'syllabus', 'estimate', 'No written syllabus. The preliminary round is an audition (prepared monologues/scenes, songs, movement); shortlisted candidates attend a 3–5 day workshop and interview.', 'Based on the exam''s usual pattern in recent years.', null, null, null, null),
  ('PAU CET', 'syllabus', 'estimate', 'Physics, Chemistry and Mathematics or Biology (Agriculture for some courses) at the Class 12 level (Punjab board / NCERT).', 'Based on the exam''s usual pattern in recent years.', null, null, null, null)
) v(match, field, kind, value_text, basis, source_name, source_url, value_min, value_max)
join public.exams t on t.name = v.match
on conflict (entity, record_id, field) do update set
  kind = excluded.kind, value_text = excluded.value_text, basis = excluded.basis,
  source_name = excluded.source_name, source_url = excluded.source_url,
  value_min = excluded.value_min, value_max = excluded.value_max, updated_at = now();

