  ('air-force-agniveer', 'salary', 'estimate', '₹30,000 a month in year 1 rising to ₹40,000 in year 4 (about ₹21,000–28,000 in hand after the Agniveer Corpus Fund contribution), plus about ₹10 lakh Seva Nidhi on exit after 4 years.', 'Based on the Agnipath scheme''s published pay structure.', null, null, '360000', '480000'),
  ('navy-agniveer', 'salary', 'estimate', '₹30,000 a month in year 1 rising to ₹40,000 in year 4 (about ₹21,000–28,000 in hand after the Agniveer Corpus Fund contribution), plus about ₹10 lakh Seva Nidhi on exit after 4 years.', 'Based on the Agnipath scheme''s published pay structure.', null, null, '360000', '480000'),
  ('audiologist', 'salary', 'estimate', 'About ₹2.5–5 lakh a year at entry; ₹6–12 lakh a year with experience or private practice.', 'Based on typical pay reported for this role in India in recent years; varies with employer, city and experience.', null, null, '250000', '1200000'),
  ('bank-it-officer', 'salary', 'estimate', 'Scale I officer: basic about ₹48,480 a month; gross about ₹80,000–90,000 a month with DA and allowances (about ₹9–11 lakh a year).', 'Based on the 12th Bipartite Settlement pay scale for JMGS-I officers plus usual allowances.', null, null, '900000', '1100000'),
  ('chef', 'salary', 'estimate', 'About ₹2–4 lakh a year as a commis/junior chef; ₹6–15 lakh as sous or head chef in good hotels; executive chefs ₹20 lakh+.', 'Based on typical pay reported for this role in India in recent years; varies with employer, city and experience.', null, null, '200000', '1500000'),
  ('cinematographer', 'salary', 'estimate', 'Assistants earn about ₹1.5–4 lakh a year; established cinematographers are paid per project (roughly ₹50,000 to several lakh per project).', 'Based on typical pay reported for this role in India in recent years; varies with employer, city and experience.', null, null, '150000', '1000000'),
  ('cisf-constable', 'salary', 'estimate', 'Pay Level 3 (basic ₹21,700–69,100); about ₹35,000–40,000 a month gross at entry with allowances.', 'Based on the 7th Pay Commission pay level for this post plus usual allowances; in-hand pay depends on city and deductions.', null, null, '420000', '480000'),
  ('crpf-constable', 'salary', 'estimate', 'Pay Level 3 (basic ₹21,700–69,100); about ₹35,000–40,000 a month gross at entry with allowances.', 'Based on the 7th Pay Commission pay level for this post plus usual allowances; in-hand pay depends on city and deductions.', null, null, '420000', '480000'),
  ('coast-guard-navik', 'salary', 'estimate', 'Navik (GD) Pay Level 3 (basic ₹21,700); about ₹35,000–40,000 a month gross with allowances.', 'Based on the 7th Pay Commission pay level for this post plus usual allowances; in-hand pay depends on city and deductions.', null, null, '420000', '480000'),
  ('clinical-psychologist', 'salary', 'estimate', 'About ₹4–7 lakh a year at entry for RCI-registered clinical psychologists; ₹8–15 lakh+ with experience or private practice.', 'Based on typical pay reported for this role in India in recent years; varies with employer, city and experience.', null, null, '400000', '1500000'),
  ('commercial-pilot', 'salary', 'estimate', 'First officers at Indian airlines earn about ₹1–2 lakh a month (₹12–25 lakh a year); captains about ₹4–8 lakh a month.', 'Based on typical pay reported for this role in India in recent years; varies with employer, city and experience.', null, null, '1200000', '9600000'),
  ('cost-management-accountant', 'salary', 'estimate', 'About ₹6–12 lakh a year for newly qualified CMAs; ₹15–30 lakh in senior finance roles.', 'Based on typical pay reported for this role in India in recent years; varies with employer, city and experience.', null, null, '600000', '3000000'),
  ('film-editor', 'salary', 'estimate', 'About ₹2–5 lakh a year starting; experienced editors ₹8–20 lakh a year or per-project fees.', 'Based on typical pay reported for this role in India in recent years; varies with employer, city and experience.', null, null, '200000', '2000000'),
  ('footwear-designer', 'salary', 'estimate', 'About ₹3–5 lakh a year starting; ₹8–15 lakh with experience.', 'Based on typical pay reported for this role in India in recent years; varies with employer, city and experience.', null, null, '300000', '1500000'),
  ('forensic-scientist', 'salary', 'estimate', 'Government Scientific Assistant/Officer posts: Pay Level 6–10 (about ₹35,000–1,00,000 a month gross); private labs about ₹3–8 lakh a year.', 'Based on typical pay reported for this role in India in recent years; varies with employer, city and experience.', null, null, '300000', '1200000'),
  ('investment-adviser', 'salary', 'estimate', 'About ₹4–8 lakh a year as an associate; independent fee-based advisers often earn ₹10–30 lakh+ depending on clients.', 'Based on typical pay reported for this role in India in recent years; varies with employer, city and experience.', null, null, '400000', '3000000'),
  ('kvs-teacher', 'salary', 'estimate', 'PRT Level 6 (basic ₹35,400), TGT Level 7 (₹44,900), PGT Level 8 (₹47,600) plus DA and HRA — roughly ₹55,000–85,000 a month gross.', 'Based on the 7th Pay Commission pay level for this post plus usual allowances; in-hand pay depends on city and deductions.', null, null, '660000', '1020000'),
  ('lic-aao', 'salary', 'estimate', 'Basic pay about ₹53,600 a month (scale up to ₹1,02,090); gross about ₹85,000–95,000 a month in metro cities.', 'Based on LIC''s AAO pay scale in its recent notifications plus usual allowances.', null, null, '1000000', '1150000'),
  ('loco-pilot', 'salary', 'estimate', 'Assistant Loco Pilot: Pay Level 2 (basic ₹19,900); with running allowance usually about ₹35,000–50,000 a month.', 'Based on the 7th Pay Commission pay level for this post plus usual allowances; in-hand pay depends on city and deductions.', null, null, '420000', '600000'),
  ('merchant-navy-officer', 'salary', 'estimate', 'Deck/engine cadets get a stipend; junior officers about US$2,000–5,000 a month; captains/chief engineers about US$10,000–15,000 a month (often tax-free for NRIs).', 'Based on typical pay reported for this role in India in recent years; varies with employer, city and experience.', null, null, null, null),
  ('meteorologist', 'salary', 'estimate', 'IMD Scientist-B: Pay Level 10 (basic ₹56,100), about ₹1 lakh a month gross; private weather firms about ₹4–10 lakh a year.', 'Based on typical pay reported for this role in India in recent years; varies with employer, city and experience.', null, null, '400000', '1200000'),
  ('mutual-fund-distributor', 'salary', 'estimate', 'Commission-based: trail commission is roughly 0.5–1% a year of the assets managed — about ₹5–10 lakh a year on ₹10 crore of client assets.', 'Based on typical pay reported for this role in India in recent years; varies with employer, city and experience.', null, null, null, null),
  ('nuclear-scientist-barc', 'salary', 'estimate', 'Scientific Officer (C): Pay Level 10 (basic ₹56,100), about ₹1 lakh+ a month gross after training; a monthly stipend is paid during training.', 'Based on the 7th Pay Commission pay level for this post plus usual allowances; in-hand pay depends on city and deductions.', null, null, '1200000', '1400000'),
  ('pastry-chef', 'salary', 'estimate', 'About ₹2–4 lakh a year starting; ₹6–12 lakh for pastry chefs in premium hotels.', 'Based on typical pay reported for this role in India in recent years; varies with employer, city and experience.', null, null, '200000', '1200000'),
  ('patent-agent', 'salary', 'estimate', 'About ₹4–8 lakh a year at entry in IP firms; ₹12–25 lakh+ with experience.', 'Based on typical pay reported for this role in India in recent years; varies with employer, city and experience.', null, null, '400000', '2500000'),
  ('prosthetist-orthotist', 'salary', 'estimate', 'About ₹2.5–5 lakh a year starting; ₹6–10 lakh with experience.', 'Based on typical pay reported for this role in India in recent years; varies with employer, city and experience.', null, null, '250000', '1000000'),
  ('research-analyst', 'salary', 'estimate', 'About ₹5–10 lakh a year at entry; ₹15–30 lakh+ for senior analysts.', 'Based on typical pay reported for this role in India in recent years; varies with employer, city and experience.', null, null, '500000', '3000000'),
  ('sound-designer', 'salary', 'estimate', 'About ₹2–5 lakh a year starting; experienced designers ₹8–20 lakh a year or per project.', 'Based on typical pay reported for this role in India in recent years; varies with employer, city and experience.', null, null, '200000', '2000000'),
  ('stock-broker', 'salary', 'estimate', 'Dealers about ₹3–6 lakh a year; senior dealers/relationship managers ₹8–15 lakh plus incentives.', 'Based on typical pay reported for this role in India in recent years; varies with employer, city and experience.', null, null, '300000', '1500000'),
  ('yoga-instructor', 'salary', 'estimate', 'About ₹2–4 lakh a year starting (₹15,000–35,000 a month); senior certified trainers ₹6–12 lakh; private classes ₹500–2,000 a session.', 'Based on typical pay reported for this role in India in recent years; varies with employer, city and experience.', null, null, '200000', '1200000'),
  ('mathematician', 'salary', 'estimate', 'While training: research fellowships of ₹37,000 a month (JRF) rising to ₹42,000 (SRF) — the rates ISI and CMI pay. After a PhD: postdoctoral positions roughly ₹60,000–80,000 a month; Assistant Professor at IITs, IISERs and universities on Pay Level 10–12 (basic ₹57,700–1,01,500), about ₹1–2 lakh a month gross. Industry research and quantitative roles for mathematicians commonly ₹15–40 lakh a year.', 'Based on typical pay reported for this role in India in recent years; varies with employer, city and experience.', null, null, '444000', '4000000'),
  ('statistician', 'salary', 'estimate', 'Junior Statistical Officer (through SSC CGL): Pay Level 6 (basic ₹35,400), about ₹55,000–65,000 a month gross. Private-sector statisticians and analysts about ₹5–12 lakh a year at entry and ₹15–30 lakh with experience; ISI M.Stat graduates often start around ₹15–30 lakh.', 'Based on typical pay reported for this role in India in recent years; varies with employer, city and experience.', null, null, '500000', '3000000'),
  ('indian-statistical-service-officer', 'salary', 'estimate', 'Junior Time Scale officers start on Pay Level 10 (basic ₹56,100) plus DA and HRA — about ₹1–1.2 lakh a month gross — rising through Senior Time Scale and above with promotions.', 'Based on the 7th Pay Commission pay level for this post plus usual allowances; in-hand pay depends on city and deductions.', null, null, '1200000', '1450000'),
  ('quantitative-analyst', 'how_to_enter', 'estimate', 'Eligibility: Class 12 with Mathematics; no fixed degree, but most quants study mathematics, statistics, computer science or engineering.
Route: B.Stat/B.Math at ISI (ISI Admission Test), B.S. at CMI (CMI entrance) or a B.Tech at an IIT (JEE Advanced), often followed by M.Stat, M.Math or a master''s in financial engineering → strong probability, statistics and C++/Python → campus or off-campus quant interviews (probability puzzles, coding, finance basics) at trading firms, hedge funds and banks.', 'Based on the usual eligibility and entry routes for this career in India.', null, null, null, null),
  ('quantitative-analyst', 'salary', 'estimate', 'Freshers at leading quant and high-frequency trading firms in India: roughly ₹25–60 lakh a year in total pay; quant roles at banks roughly ₹12–25 lakh. Experienced quants commonly ₹50 lakh to over ₹1 crore a year, much of it as bonus.', 'Based on typical pay reported for this role in India in recent years; varies with employer, city and experience.', null, null, '1200000', '6000000'),
  ('cryptographer', 'salary', 'estimate', 'Government research posts (e.g. DRDO scientists): Pay Level 10 (basic ₹56,100), about ₹1 lakh a month gross. Industry cryptography and security engineers roughly ₹10–25 lakh a year at entry and ₹30–60 lakh with experience.', 'Based on typical pay reported for this role in India in recent years; varies with employer, city and experience.', null, null, '1000000', '6000000'),
  ('operations-research-analyst', 'salary', 'estimate', 'Roughly ₹6–12 lakh a year at entry; graduates of ISI''s M.Tech (QROR) and IIT industrial-engineering programmes often ₹12–20 lakh. About ₹20–40 lakh a year with experience in analytics, supply chain or consulting.', 'Based on typical pay reported for this role in India in recent years; varies with employer, city and experience.', null, null, '600000', '4000000'),
  ('ias-officer', 'salary', 'estimate', 'Pay Level 10 at entry (basic ₹56,100 a month); about ₹1–1.3 lakh a month gross with DA and HRA. Promotions take IAS officers up to Level 17 (₹2,25,000) and the Cabinet Secretary to Level 18 (₹2,50,000), with official housing and vehicle.', 'Group A central services start at Pay Level 10 of the 7th Pay Commission matrix (basic ₹56,100 a month); gross pay adds DA, HRA and allowances and depends on the city. UPSC''s notification itself does not state pay.', null, null, '1200000', '1550000'),
  ('ips-officer', 'salary', 'estimate', 'Pay Level 10 at entry (basic ₹56,100 a month); about ₹1–1.3 lakh a month gross with DA and HRA. Promotions lead up to Director General of Police at Level 16–17, with official housing and vehicle.', 'Group A central services start at Pay Level 10 of the 7th Pay Commission matrix (basic ₹56,100 a month); gross pay adds DA, HRA and allowances and depends on the city. UPSC''s notification itself does not state pay.', null, null, '1200000', '1550000'),
  ('irs-income-tax-officer', 'salary', 'estimate', 'Pay Level 10 at entry (basic ₹56,100 a month); about ₹1–1.3 lakh a month gross with DA and HRA.', 'Group A central services start at Pay Level 10 of the 7th Pay Commission matrix (basic ₹56,100 a month); gross pay adds DA, HRA and allowances and depends on the city. UPSC''s notification itself does not state pay.', null, null, '1200000', '1550000'),
  ('irs-customs-indirect-taxes-officer', 'salary', 'estimate', 'Pay Level 10 at entry (basic ₹56,100 a month); about ₹1–1.3 lakh a month gross with DA and HRA.', 'Group A central services start at Pay Level 10 of the 7th Pay Commission matrix (basic ₹56,100 a month); gross pay adds DA, HRA and allowances and depends on the city. UPSC''s notification itself does not state pay.', null, null, '1200000', '1550000'),
